int inside = 0, outside = 0;
std::random_device rd;
std::mt19937 e2(rd());
std::uniform_real_distribution<> dist(0, 6);
std::uniform_real_distribution<> distx(tree.bb.minX(), tree.bb.maxX());
std::uniform_real_distribution<> disty(tree.bb.minY(), tree.bb.maxY());
std::uniform_real_distribution<> distz(tree.bb.minZ(), tree.bb.maxZ());
for (int i = 0; i < numberOfChecks; i++) {
    Point3d boundingPoint;
    double n1, n2;
    int side = std::floor(dist(e2));
    switch(side % 3){
        case 0: 
            n1 = disty(e2);
            n2 = distz(e2);
            boundingPoint.setY(n1);
            boundingPoint.setZ(n2);
            if (side == 0) 
                boundingPoint.setX(tree.bb.minX());
            else 
                boundingPoint.setX(tree.bb.maxX());
            break;
        case 1: 
            n1 = distx(e2);
            n2 = distz(e2);
            boundingPoint.setX(n1);
            boundingPoint.setZ(n2);
            if (side == 1) 
                boundingPoint.setY(tree.bb.minY());
            else 
                boundingPoint.setY(tree.bb.maxY());
            break;
        case 2: 
            n1 = distx(e2);
            n2 = disty(e2);
            boundingPoint.setX(n1);
            boundingPoint.setY(n2);
            if (side == 2) 
                boundingPoint.setZ(tree.bb.minZ());
            else 
                boundingPoint.setZ(tree.bb.maxZ());
            break;
    }
    int count = tree.numberIntersectedPrimitives(p, boundingPoint);
    if (count % 2 == 1) 
        inside++;
    else 
        outside++;
}
return inside > outside;

